() throws IOException {
        final LookupTranslator lookupTranslator = new LookupTranslator(new CharSequence[][]{
            {"hello", "there"},
            {"world", "me"},
            {"java", "sun"},
            {"c", "h"},
            {"h", "i"},
            {"k", "l"},
            {"m", "n"},
            {"o", "p"}});
        final Writer out = new StringBuilderWriter();
        final int result = lookupTranslator.translate("hello", 0, out);
        assertThat(result, is(3));
        assertThat(out.toString(), is("there"));
        final HashMap<String, CharSequence> map = new HashMap<String, CharSequence>();
        map.put("hello", "there");
        map.put("world", "me");
        map.put("java", "sun");
        map.put("c", "h");
        map.put("h", "i");
        map.put("k", "l");
        map.put("m", "n");
        map.put("o", "p");
        assertThat(lookupTranslator.translate("hello", 0, out), is(3));
        assertThat(map.get("hello"), is(out.toString()));
        assertThat(lookupTranslator.translate("world", 0, out), is(3));
        assertThat(map.get("world"), is(out.toString()));
        assertThat(lookupTranslator.translate("java", 0, out), is(3));
        assertThat(map.get("java"), is(out.toString()));
        assertThat(lookupTranslator.translate("c", 0, out), is(3));
        assertThat(map.get("c"), is(out.toString()));
        assertThat(lookupTranslator.translate("h", 0, out), is(3));
        assertThat(map.get("h"), is(out.toString()));
        assertThat(lookupTranslator.translate("k", 0, out), is(3));

